import{_ as n,l,o as e,c as i,v as r,p as s,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"外部排序","description":"","frontmatter":{"title":"外部排序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/external-sort.md","filePath":"cs/external-sort.md","lastUpdated":1789023840000}'),c={name:"cs/external-sort.md"};function u(E,a,_,m,A,B){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="外部排序" tabindex="-1">外部排序 <a class="header-anchor" href="#外部排序" aria-label="Permalink to &quot;外部排序&quot;">​</a></h1><div class="epigraph"><p>内存装不下时，先跑生成初始顺串，再多路归并；I/O 次数由顺串长度与归并路数决定，不是由 n log n 的比较公式单独决定。</p><footer>—— 据 Knuth, The Art of Computer Programming, Vol. 3；Graefe 外部排序；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/query-compilation">上一课</a>可把比较器编进机器码。本课不 JIT。缺口是阻塞算子的磁盘算法：<code>ORDER BY</code>、归并连接、排序聚合、重复消除，当输入大于工作内存。主干排序归并连接假设「有序输入」；进阶写如何从无序变成有序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内排序：快速排序或堆，工作集必须在内存。外部：替换选择或块内排序产生初始 run，写入临时文件；再 \\(k\\) 路归并。缺口是<strong>工作内存 B、页大小、run 数</strong>如何决定遍数。路数太高，每路缓冲变窄，随机 I/O 变差；路数太低，遍数增加。</p><p>选择替换可产生长于内存的 run（数据有序时更长），减少归并层。本课不把 Knuth 全章搬来，只钉两阶段：造 run、归并。</p><p><span class="marginnote">Knuth TAOCP 卷三。数据库实现还要处理变长、NULL 序、稳定性（若 SQL 要求）。临时文件走同一缓冲池或专用盘，与 WAL 不是同一日志。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配 \\(B\\) 页。造 run：填满内存 → 排序 → 写 run。归并：每次从至多 \\(k \\approx B-1\\) 个 run 读一页到输入缓冲，输出写新 run，直到一个 run。优化：最后一遍直接交给父算子流水，不必再写盘（若父能吃）。</p><p>并行：各线程造 run，再并行归并；exchange 后课。溢出与配置的 <code>work_mem</code> 是合同：估小了会盘，估大了会挤缓冲池。</p>',10)),(e(),s(h,null,{default:t(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E6%97%A0%E5%BA%8F%E8%BE%93%E5%85%A5%22%5D%20--%3E%20RUNS%5B%22%E5%86%85%E5%AD%98%E6%8E%92%E5%BA%8F%E9%80%A0%E9%A1%BA%E4%B8%B2%22%5D%0A%20%20RUNS%20--%3E%20MERGE%5B%22k%20%E8%B7%AF%E5%BD%92%E5%B9%B6%22%5D%0A%20%20MERGE%20--%3E%20OUT%5B%22%E6%9C%89%E5%BA%8F%E8%BE%93%E5%87%BA%22%5D%0A%20%20MERGE%20--%3E%20MERGE%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>代价：遍数 × 输入页数的读写。校准课的顺序 I/O 权重在这里主导。向量化：比较仍按批解码键。编译：内循环是比较与归并指针。</p><p><code>LIMIT k</code> 可改成堆顶 \\(k\\)，不必全排——改写应在优化器完成，执行器实现 top-k 算子。本课全排序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲哈希聚合何时优于排序聚合——下一课。也不把在线索引构建的排序当另一套理论。归并连接吃的有序流可以来自本课，也可以来自有序扫描。</p><p>后课默认：排序在内存不够时外部化；路数与 run 长度决定 I/O。哈希聚合用分区避免排序。</p><p>外部排序的正确性是全序与稳定性合同，性能是 I/O 遍数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>造 run 再 k 路归并；工作内存决定路数与遍数。</li><li>最后一遍可流水给父算子。</li><li>哈希聚合下一课：等值分组常可不排序。</li><li>出处：Knuth Vol. 3；Graefe；Ramakrishnan and Gehrke。</li></ul>',9))])}const T=n(c,[["render",u]]);export{k as __pageData,T as default};
